1	// The constructor keeps public named params (`remoteDataSource`,
2	// `entriesBox`) distinct from the private fields they initialize, matching
3	// `account_settings_repository_impl.dart`'s documented convention.
4	// ignore_for_file: prefer_initializing_formals
5	import 'package:fpdart/fpdart.dart';
6	import 'package:hive_ce/hive_ce.dart';
7	
8	import '../../../../core/failure/failure.dart';
9	import '../../domain/entities/entries_page.dart';
10	import '../../domain/entities/entry.dart';
11	import '../../domain/repositories/entries_repository.dart';
12	import '../datasources/entries_remote_data_source.dart';
13	import '../models/entry_dto.dart';
14	
15	/// On success, writes the entry through to the `entries` Hive box (`Box
16	/// <Map>`, keyed by id, raw `EntryDto.toJson()` — Design Notes) *before*
17	/// returning `right(...)`, same "persist then return" ordering
18	/// `AuthRepositoryImpl._authenticate` already uses for its own
19	/// post-success side effect.
20	class EntriesRepositoryImpl implements EntriesRepository {
21	  EntriesRepositoryImpl({
22	    required EntriesRemoteDataSource remoteDataSource,
23	    required Box<Map> entriesBox,
24	  }) : _remoteDataSource = remoteDataSource,
25	       _entriesBox = entriesBox;
26	
27	  final EntriesRemoteDataSource _remoteDataSource;
28	  final Box<Map> _entriesBox;
29	
30	  @override
31	  Future<Either<Failure, Entry>> create({
32	    required String content,
33	    required EntrySource source,
34	    int? mediaDurationSeconds,
35	  }) async {
36	    final result = await _remoteDataSource.create(
37	      content: content,
38	      source: source,
39	      mediaDurationSeconds: mediaDurationSeconds,
40	    );
41	    return result.match((failure) async => left(failure), (dto) async {
42	      // A thrown Hive/disk exception must never escape unmapped (RNF09) —
43	      // same rationale/fallback `AuthRepositoryImpl` already uses for its
44	      // own local-persistence step.
45	      try {
46	        await _entriesBox.put(dto.id, dto.toJson());
47	      } catch (error) {
48	        return left(Failure.malformedResponse(message: error.toString()));
49	      }
50	      return right(_toEntry(dto));
51	    });
52	  }
53	
54	  @override
55	  Future<Either<Failure, EntriesPage>> list({
56	    String? cursor,
57	    int limit = 20,
58	  }) async {
59	    final result = await _remoteDataSource.list(cursor: cursor, limit: limit);
60	    return result.match(
61	      (failure) async {
62	        // Boundaries: only these two specific failures fall back to the
63	        // Hive cache — every other code (e.g. `authExpired`) propagates
64	        // unmapped (RNF09).
65	        if (failure is NetworkOffline || failure is NetworkTimeout) {
66	          return _offlineFallback();
67	        }
68	        return left(failure);
69	      },
70	      (page) async {
71	        try {
72	          for (final dto in page.items) {
73	            await _entriesBox.put(dto.id, dto.toJson());
74	          }
75	        } catch (error) {
76	          // Same RNF09 rationale as `create()`'s own Hive-write guard — a
77	          // thrown Hive/disk exception must never escape unmapped.
78	          return left(Failure.malformedResponse(message: error.toString()));
79	        }
80	        return right(
81	          EntriesPage(
82	            items: page.items.map(_toEntry).toList(),
83	            nextCursor: page.nextCursor,
84	          ),
85	        );
86	      },
87	    );
88	  }
89	
90	  /// The offline/timeout fallback (Boundaries): a full `entries` Hive box
91	  /// dump, sorted `occurredAt` desc, always `nextCursor: null` — a cached
92	  /// dump has no further page to request. A corrupt cached entry (should
93	  /// never happen — every entry here was written by [create]/[list]
94	  /// themselves) maps to `Left(malformedResponse)` rather than throwing
95	  /// (RNF09), same guard `create()`'s own Hive write already has.
96	  Either<Failure, EntriesPage> _offlineFallback() {
97	    try {
98	      final entries =
99	          _entriesBox.values
100	              .map(
101	                (json) => _toEntry(
102	                  EntryDto.fromJson(Map<String, dynamic>.from(json)),
103	                ),
104	              )
105	              .toList()
106	            ..sort(
107	              (a, b) =>
108	                  DateTime.parse(b.occurredAt)
109	                      .compareTo(DateTime.parse(a.occurredAt)),
110	            );
111	      return right(EntriesPage(items: entries, nextCursor: null));
112	    } catch (error) {
113	      return left(Failure.malformedResponse(message: error.toString()));
114	    }
115	  }
116	
117	  Entry _toEntry(EntryDto dto) => Entry(
118	    id: dto.id,
119	    content: dto.content,
120	    source: dto.source,
121	    chatMessageId: dto.chatMessageId,
122	    occurredAt: dto.occurredAt,
123	    serverRevision: dto.serverRevision,
124	    createdAt: dto.createdAt,
125	    updatedAt: dto.updatedAt,
126	    mediaDurationSeconds: dto.mediaDurationSeconds,
127	  );
128	}
