1	import 'package:flutter_bloc/flutter_bloc.dart';
2	
3	import '../../domain/repositories/entries_repository.dart';
4	import 'meus_registros_state.dart';
5	
6	/// Drives `MeusRegistrosScreen` — calls `EntriesRepository.list()` directly
7	/// (no use-case layer, matching this codebase's existing small-scope
8	/// convention: `AccountSettingsCubit`/`AuthCubit`/`TextEntryCubit`). A
9	/// `lazySingleton` (Code Map), like `AccountSettingsCubit` — long-lived, so
10	/// the already-fetched pages survive leaving and re-entering
11	/// `/meus-registros` within the same app session.
12	class MeusRegistrosCubit extends Cubit<MeusRegistrosState> {
13	  MeusRegistrosCubit(this._repository) : super(const MeusRegistrosLoading());
14	
15	  final EntriesRepository _repository;
16	
17	  /// `MeusRegistrosScreen.initState` calls this once, every mount — always
18	  /// re-fetches from scratch rather than keeping a previous visit's page
19	  /// around, since a new entry may have been saved (Insertion Modal, Epic
20	  /// 3) since the last visit.
21	  Future<void> loadFirstPage() async {
22	    emit(const MeusRegistrosLoading());
23	    final result = await _repository.list();
24	    // Mirrors `AccountSettingsCubit.toggleBiometric`'s own guard: `close()`
25	    // can race this awaited call (e.g. a fast app teardown mid-request) —
26	    // `emit()` after `close()` would otherwise throw.
27	    if (isClosed) {
28	      return;
29	    }
30	    result.match(
31	      (failure) => emit(MeusRegistrosError(message: failure.message)),
32	      (page) {
33	        if (page.items.isEmpty) {
34	          emit(const MeusRegistrosEmpty());
35	          return;
36	        }
37	        emit(
38	          MeusRegistrosLoaded(entries: page.items, nextCursor: page.nextCursor),
39	        );
40	      },
41	    );
42	  }
43	
44	  /// `MeusRegistrosScreen`'s scroll listener calls this near the list's
45	  /// end. A no-op while not [MeusRegistrosLoaded], while
46	  /// [MeusRegistrosLoaded.nextCursor] is already `null`, while a call is
47	  /// already in flight, or — critically — once
48	  /// [MeusRegistrosLoaded.loadMoreFailed] is already `true`: without that
49	  /// last guard, a failed page's own footer swapping from a spinner to a
50	  /// "Tentar novamente" button can shift the list's `maxScrollExtent`
51	  /// just enough to leave the scroll position still inside the
52	  /// pre-fetch-buffer zone, re-firing this same listener and retrying
53	  /// forever — observed directly as an unbounded `pumpAndSettle` loop in
54	  /// this screen's own widget test. Once failed, only an explicit
55	  /// [retryLoadMore] (the footer's own button) tries again.
56	  Future<void> loadMore() => _fetchMore(isRetry: false);
57	
58	  /// The footer's "Tentar novamente" button — the one path allowed to
59	  /// retry past a [MeusRegistrosLoaded.loadMoreFailed] of `true`
60	  /// ([loadMore]'s own doc).
61	  Future<void> retryLoadMore() => _fetchMore(isRetry: true);
62	
63	  Future<void> _fetchMore({required bool isRetry}) async {
64	    final current = state;
65	    if (current is! MeusRegistrosLoaded ||
66	        current.nextCursor == null ||
67	        current.isLoadingMore ||
68	        (current.loadMoreFailed && !isRetry)) {
69	      return;
70	    }
71	    emit(current.copyWith(isLoadingMore: true, loadMoreFailed: false));
72	    final result = await _repository.list(cursor: current.nextCursor);
73	    if (isClosed) {
74	      return;
75	    }
76	    // Re-reads `state` rather than closing over `current` — defensive
77	    // against `loadFirstPage()` having reset the state to something other
78	    // than `MeusRegistrosLoaded` while this await was pending.
79	    final latest = state;
80	    if (latest is! MeusRegistrosLoaded) {
81	      return;
82	    }
83	    result.match(
84	      (failure) =>
85	          emit(latest.copyWith(isLoadingMore: false, loadMoreFailed: true)),
86	      (page) {
87	        // I/O matrix: "Next page appended, no dup ids" — defensive
88	        // de-duplication in case a cursor-boundary entry is ever repeated
89	        // by the server.
90	        final existingIds = latest.entries.map((entry) => entry.id).toSet();
91	        final newEntries = page.items.where(
92	          (entry) => !existingIds.contains(entry.id),
93	        );
94	        emit(
95	          MeusRegistrosLoaded(
96	            entries: [...latest.entries, ...newEntries],
97	            nextCursor: page.nextCursor,
98	          ),
99	        );
100	      },
101	    );
102	  }
103	}
