1	import 'entry.dart';
2	
3	/// One calendar day's worth of entries — [date] is truncated to midnight
4	/// *local* time (never UTC, never [Entry.createdAt]; Boundaries), so two
5	/// entries whose [Entry.occurredAt] fall on the same local day always land
6	/// in the same group regardless of the UTC offset the backend sent them in.
7	class EntryDateGroup {
8	  const EntryDateGroup({required this.date, required this.entries});
9	
10	  /// Always a `DateTime` with zeroed time-of-day fields (`DateTime(y, m,
11	  /// d)`) — day-label formatting ("Hoje"/"Ontem"/a date string) is
12	  /// presentation's job (Boundaries), not this pure entity's.
13	  final DateTime date;
14	
15	  final List<Entry> entries;
16	
17	  @override
18	  bool operator ==(Object other) =>
19	      identical(this, other) ||
20	      (other is EntryDateGroup &&
21	          other.date == date &&
22	          _listEquals(other.entries, entries));
23	
24	  @override
25	  int get hashCode => Object.hash(date, Object.hashAll(entries));
26	
27	  @override
28	  String toString() =>
29	      'EntryDateGroup(date: $date, entries: ${entries.length})';
30	}
31	
32	/// Groups [entries] by their [Entry.occurredAt]'s local calendar day
33	/// (Boundaries: "never `createdAt`"). Pure Dart — no `package:flutter`
34	/// import (RNF06), since `entries/domain` must stay flutter-free.
35	///
36	/// Preserves [entries]' own relative order within each group, and orders
37	/// the returned groups by each one's first-encountered entry — callers
38	/// (`EntriesRepository.list()`/`MeusRegistrosCubit`) always pass entries
39	/// already newest-first, so that ordering alone already yields groups
40	/// newest-day-first with no separate sort step needed here.
41	///
42	/// An empty [entries] list yields an empty list of groups (the "zero
43	/// entries" edge case) — never a single empty group.
44	List<EntryDateGroup> groupEntriesByDate(List<Entry> entries) {
45	  final entriesByDay = <DateTime, List<Entry>>{};
46	  final dayOrder = <DateTime>[];
47	
48	  for (final entry in entries) {
49	    final occurredAt = DateTime.parse(entry.occurredAt).toLocal();
50	    final day = DateTime(occurredAt.year, occurredAt.month, occurredAt.day);
51	    final bucket = entriesByDay.putIfAbsent(day, () {
52	      dayOrder.add(day);
53	      return <Entry>[];
54	    });
55	    bucket.add(entry);
56	  }
57	
58	  return [
59	    for (final day in dayOrder)
60	      EntryDateGroup(date: day, entries: entriesByDay[day]!),
61	  ];
62	}
63	
64	bool _listEquals(List<Entry> a, List<Entry> b) {
65	  if (a.length != b.length) {
66	    return false;
67	  }
68	  for (var i = 0; i < a.length; i++) {
69	    if (a[i] != b[i]) {
70	      return false;
71	    }
72	  }
73	  return true;
74	}
