1	import 'package:flutter_test/flutter_test.dart';
2	import 'package:fpdart/fpdart.dart';
3	import 'package:hive_ce/hive_ce.dart';
4	import 'package:mocktail/mocktail.dart';
5	
6	import 'package:cerne/core/failure/failure.dart';
7	import 'package:cerne/features/entries/data/datasources/entries_remote_data_source.dart';
8	import 'package:cerne/features/entries/data/models/entry_dto.dart';
9	import 'package:cerne/features/entries/data/repositories/entries_repository_impl.dart';
10	import 'package:cerne/features/entries/domain/entities/entry.dart';
11	
12	class MockEntriesRemoteDataSource extends Mock
13	    implements EntriesRemoteDataSource {}
14	
15	class MockBox extends Mock implements Box<Map> {}
16	
17	const _dto = EntryDto(
18	  id: 'e1',
19	  content: 'Hoje foi um bom dia.',
20	  source: EntrySource.manual,
21	  chatMessageId: null,
22	  occurredAt: '2026-01-01T00:00:00Z',
23	  serverRevision: 1,
24	  createdAt: '2026-01-01T00:00:00Z',
25	  updatedAt: '2026-01-01T00:00:00Z',
26	);
27	
28	EntryDto _listDto(String id, String occurredAt) => EntryDto(
29	  id: id,
30	  content: 'content-$id',
31	  source: EntrySource.manual,
32	  chatMessageId: null,
33	  occurredAt: occurredAt,
34	  serverRevision: 1,
35	  createdAt: occurredAt,
36	  updatedAt: occurredAt,
37	);
38	
39	/// Covers spec-3-1's I/O & Edge-Case Matrix for `EntriesRepository.create`:
40	/// - success -> maps the `EntryDto` to `Entry` and writes it through to
41	///   the Hive box, keyed by id, *before* returning `Right`.
42	/// - failure (incl. offline) -> `Left(Failure)`, the box is never touched.
43	void main() {
44	  late MockEntriesRemoteDataSource mockRemoteDataSource;
45	  late MockBox mockBox;
46	  late EntriesRepositoryImpl repository;
47	
48	  setUpAll(() {
49	    registerFallbackValue(EntrySource.manual);
50	  });
51	
52	  setUp(() {
53	    mockRemoteDataSource = MockEntriesRemoteDataSource();
54	    mockBox = MockBox();
55	    when(() => mockBox.put(any(), any())).thenAnswer((_) async {});
56	    repository = EntriesRepositoryImpl(
57	      remoteDataSource: mockRemoteDataSource,
58	      entriesBox: mockBox,
59	    );
60	  });
61	
62	  group('create() — success', () {
63	    test('writes EntryDto.toJson() to the Hive box keyed by id, then returns '
64	        'Right(Entry) mapped from the dto', () async {
65	      when(
66	        () => mockRemoteDataSource.create(
67	          content: any(named: 'content'),
68	          source: any(named: 'source'),
69	        ),
70	      ).thenAnswer((_) async => right(_dto));
71	
72	      final result = await repository.create(
73	        content: 'Hoje foi um bom dia.',
74	        source: EntrySource.manual,
75	      );
76	
77	      verify(() => mockBox.put('e1', _dto.toJson())).called(1);
78	      expect(result.isRight(), isTrue);
79	      result.match((_) => fail('expected Right'), (entry) {
80	        expect(entry.id, 'e1');
81	        expect(entry.content, 'Hoje foi um bom dia.');
82	        expect(entry.source, EntrySource.manual);
83	        expect(entry.serverRevision, 1);
84	      });
85	    });
86	
87	    test('spec-3-2: a non-null mediaDurationSeconds is threaded through to '
88	        'the remote data source and onto the mapped Entry', () async {
89	      const audioDto = EntryDto(
90	        id: 'e2',
91	        content: 'Transcrição de áudio.',
92	        source: EntrySource.audio,
93	        chatMessageId: null,
94	        occurredAt: '2026-01-01T00:00:00Z',
95	        serverRevision: 1,
96	        createdAt: '2026-01-01T00:00:00Z',
97	        updatedAt: '2026-01-01T00:00:00Z',
98	        mediaDurationSeconds: 7,
99	      );
100	      when(
101	        () => mockRemoteDataSource.create(
102	          content: any(named: 'content'),
103	          source: any(named: 'source'),
104	          mediaDurationSeconds: any(named: 'mediaDurationSeconds'),
105	        ),
106	      ).thenAnswer((_) async => right(audioDto));
107	
108	      final result = await repository.create(
109	        content: 'Transcrição de áudio.',
110	        source: EntrySource.audio,
111	        mediaDurationSeconds: 7,
112	      );
113	
114	      verify(
115	        () => mockRemoteDataSource.create(
116	          content: 'Transcrição de áudio.',
117	          source: EntrySource.audio,
118	          mediaDurationSeconds: 7,
119	        ),
120	      ).called(1);
121	      result.match((_) => fail('expected Right'), (entry) {
122	        expect(entry.mediaDurationSeconds, 7);
123	      });
124	    });
125	
126	    test('a Hive write failure maps to Left(malformedResponse), never '
127	        'throws (RNF09)', () async {
128	      when(
129	        () => mockRemoteDataSource.create(
130	          content: any(named: 'content'),
131	          source: any(named: 'source'),
132	        ),
133	      ).thenAnswer((_) async => right(_dto));
134	      when(() => mockBox.put(any(), any())).thenThrow(Exception('disk full'));
135	
136	      final result = await repository.create(
137	        content: 'Hoje foi um bom dia.',
138	        source: EntrySource.manual,
139	      );
140	
141	      expect(result.isLeft(), isTrue);
142	      result.match(
143	        (failure) => expect(failure, isA<MalformedResponse>()),
144	        (_) => fail('expected Left'),
145	      );
146	    });
147	  });
148	
149	  group('create() — failure', () {
150	    test('a remote Failure (e.g. offline) passes through as Left, the Hive '
151	        'box is never touched', () async {
152	      when(
153	        () => mockRemoteDataSource.create(
154	          content: any(named: 'content'),
155	          source: any(named: 'source'),
156	        ),
157	      ).thenAnswer(
158	        (_) async => left(const Failure.networkOffline(message: 'Offline')),
159	      );
160	
161	      final result = await repository.create(
162	        content: 'Hoje foi um bom dia.',
163	        source: EntrySource.manual,
164	      );
165	
166	      expect(result.isLeft(), isTrue);
167	      result.match(
168	        (failure) => expect(failure, isA<NetworkOffline>()),
169	        (_) => fail('expected Left'),
170	      );
171	      verifyNever(() => mockBox.put(any(), any()));
172	    });
