22	/// A plain (non-mocktail) fake — this cubit's own tests need a scriptable
23	/// `list()` result per call (first page vs. a later `loadMore()` page),
24	/// which a single static mocktail stub can't express as naturally.
25	class _FakeEntriesRepository implements EntriesRepository {
26	  final List<Either<Failure, EntriesPage>> _listResults = [];
27	  final List<({String? cursor, int limit})> listCalls = [];
28	
29	  /// Queues the next `list()` call's result, in order.
30	  void queueList(Either<Failure, EntriesPage> result) {
31	    _listResults.add(result);
32	  }
33	
34	  @override
35	  Future<Either<Failure, Entry>> create({
36	    required String content,
37	    required EntrySource source,
38	    int? mediaDurationSeconds,
39	  }) async => throw UnimplementedError('not expected to be called');
40	
41	  @override
42	  Future<Either<Failure, EntriesPage>> list({
43	    String? cursor,
44	    int limit = 20,
45	  }) async {
46	    listCalls.add((cursor: cursor, limit: limit));
47	    if (_listResults.isEmpty) {
48	      throw StateError('no queued list() result for call #${listCalls.length}');
49	    }
50	    return _listResults.removeAt(0);
51	  }
52	}
