28	/// A plain (non-mocktail) fake — queues one `list()` result per call, same
29	/// rationale as `meus_registros_cubit_test.dart`'s own fake, plus an
30	/// optional [firstCallGate] so a test can hold the very first `list()`
31	/// call unresolved to observe the skeleton's 300ms threshold.
32	class _FakeEntriesRepository implements EntriesRepository {
33	  final List<Either<Failure, EntriesPage>> _listResults = [];
34	  int listCallCount = 0;
35	  Completer<void>? firstCallGate;
36	
37	  void queueList(Either<Failure, EntriesPage> result) {
38	    _listResults.add(result);
39	  }
40	
41	  @override
42	  Future<Either<Failure, Entry>> create({
43	    required String content,
44	    required EntrySource source,
45	    int? mediaDurationSeconds,
46	  }) async => throw UnimplementedError('not expected to be called');
47	
48	  @override
49	  Future<Either<Failure, EntriesPage>> list({
50	    String? cursor,
51	    int limit = 20,
52	  }) async {
53	    listCallCount++;
54	    if (listCallCount == 1 && firstCallGate != null) {
55	      await firstCallGate!.future;
56	    }
57	    if (_listResults.isEmpty) {
58	      throw StateError('no queued list() result for call #$listCallCount');
59	    }
60	    return _listResults.removeAt(0);
61	  }
62	}
