303	String _dayLabel(DateTime date) {
304	  final now = DateTime.now();
305	  final today = DateTime(now.year, now.month, now.day);
306	  final yesterday = today.subtract(const Duration(days: 1));
307	  if (date == today) {
308	    return 'Hoje';
309	  }
310	  if (date == yesterday) {
311	    return 'Ontem';
312	  }
313	  final day = date.day.toString().padLeft(2, '0');
